[SRSReportParameterAttribute(classstr(METCommonContinuingPermissionNoticeContract))]
class METTOContinuingPermissionNoticeDP extends SrsReportDataProviderPreProcessTempDB
{
    RecordInsertList insertList;
    METTOContinuingPermissionNoticeHeaderTmp header;
    METTOContinuingPermissionNoticeLineTmp line;
    InventTransferTable inventTransferTable;
    #ISOCountryRegionCodes
    #PrintMgmtSetup

    METBundleGuid         bundleHeaderReportGuid;
    METBundleGuid         headerReportGuid;

}

Method.Source:
/// <summary>
/// Set the bundling guid values to the tmp tables
/// </summary>
/// <param name = "_bundleHeaderReportGuid">Bundle header report guid</param>
/// <param name = "_headerReportGuid">Header report guid</param>
public void setBundlingGuid(METBundleGuid     _bundleHeaderReportGuid, METBundleGuid    _headerReportGuid)
{
    bundleHeaderReportGuid = _bundleHeaderReportGuid;
    headerReportGuid = _headerReportGuid;
}

/// <summary>
/// Process report
/// </summary>
public void processReport()
{
    METCommonContinuingPermissionNoticeContract contract = this.parmDataContract() as METCommonContinuingPermissionNoticeContract;

    InventTransferId TransferId = contract.parmSalesId();
    inventTransferTable = inventTransferTable::find(TransferId);

    METInventTransferTableExt metTransferExt;

    select firstonly UnderBond from metTransferExt
        where metTransferExt.InventTransferTable == inventTransferTable.RecId;

    if (inventTransferTable.RecId && metTransferExt.UnderBond && InventSite::find(InventLocation::find(inventTransferTable.InventLocationIdTo).InventSiteId).METBondedWarehouse)
    {
        this.insertHeaderData();
    }

}

/// <summary>
/// Inserts the report header data.
/// </summary>
public void insertHeaderData()
{
    NumberSequenceReference numberSequenceReference;

    numberSequenceReference = NumberSeqReference::findReference(extendedTypeNum(METCPNumber));

    if (numberSequenceReference.RecId)
    {
        // Check if CP number already exists for the transfer
        InventTransferJour inventTransferJour;
        select firstonly METCPNumber from inventTransferJour
            where inventTransferJour.TransferId == inventTransferTable.TransferId &&
            inventTransferJour.METCPNumber != '';

        if (!inventTransferJour.RecId)
        {
            METCPNumber num                         = NumberSeq::newGetNum(numberSequenceReference).num();
            header.ContinuingPermissionNoticeNumber = num;

            update_recordset inventTransferJour
            setting METCPNumber = num
                where inventTransferJour.TransferId == inventTransferTable.TransferId;
        }
    }

    InventLocation inventLocationTo = InventLocation::find(inventTransferTable.InventLocationIdTo);
    InventLocation inventLocationFrom = InventLocation::find(inventTransferTable.InventLocationIdFrom);

    // have passed industry key as its same as inventLocation.METWHSubEntity
    METIndustryKeyTable industryKey = METIndustryKeyTable::find(inventLocationFrom.METWHSubEntity);

    header.IndustryKey = industryKey.IndustryKey;
    header.CompanyCoRegNum = METIndustryKeyTable::find(industryKey.IndustryKey).CoRegNum;

    LogisticsEntityPostalAddressView postalAddressViewFrom = this.getWareHousePrimaryAddress(inventLocationFrom.RecId);
    LogisticsEntityPostalAddressView postalAddressViewTo = this.getWareHousePrimaryAddress(inventLocationTo.RecId);

    header.SendingBranchAddress         = postalAddressViewFrom.Address;
    header.SendingBranchName            = inventLocationFrom.Name;
    header.ReceivingBranchAddress       = postalAddressViewTo.Address;
    header.ReceivingBranchName          = inventLocationTo.Name;
    header.NoticeDate                   = DateTimeUtil::date(DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::getSystemDateTime(), DateTimeUtil::getUserPreferredTimeZone()));
    header.NoticeTimeString             = int2Str(DateTimeUtil::time(DateTimeUtil::utcNow()));
    header.CompanyName                  = industryKey.CompanyName;

    List metBondListFrom = strSplit(inventLocationFrom.inventSite().METBondNumber, ' ');
    Container metBondConFrom = list2con(metBondListFrom);

    header.SenderBranchExciseNumber = conpeek(metBondConFrom, 2);
    header.SenderBranchBondNumber = conpeek(metBondConFrom, 1);

    List metBondListTo = strSplit(inventLocationTo.inventSite().METBondNumber, ' ');
    Container metBondConTo = list2con(metBondListTo);

    header.ReceivingBranchExciseNumber = conpeek(metBondConTo, 2);
    header.ReceivingBranchBondNumber = conpeek(metBondConTo, 1);

    header.TransferId                           = inventTransferTable.TransferId;
    header.BundleReportHeaderGuidStr            = bundleHeaderReportGuid;
    header.ContinuingPermissionHeaderGuidStr    = headerReportGuid;

    header.insert();

    this.insertLineData();
}

/// <summary>
/// Inserts temporary line records for continuing permission notice based on transfer order lines and associated lodgement data.
/// </summary>
/// <remarks>
/// This method processes each transfer line in the current transfer order:
/// - If lodgement records already exist, it uses them directly.
/// - If no lodgement exists, it calculates applicable lodgements using getMetLodgement(),
///   which returns a list of [Lodgement ID, Available Quantity] pairs.
/// Each lodgement entry is passed to prepareRecordListTmp() to populate the temporary table.
/// Finally, all records are inserted into the database using a RecordInsertList.
/// </remarks>
public void insertLineData()
{
    InventTransferLine inventTransferLine;
    InventTable inventTable;
    METInventTable metInventTable;
    InventDim inventDim;
    METExciseInformationTable metExciseInformationTable;
    METTariffItemCodeBase tariffCodeBase;

    insertList = new RecordInsertList(tableNum(METTOContinuingPermissionNoticeLineTmp), false, false, false, false, false, line);

    // Loop through each transfer line in the current transfer order
    while select inventTransferLine
        where inventTransferLine.TransferId == inventTransferTable.TransferId
    join inventTable
        where inventTransferLine.ItemId == inventTable.ItemId
    outer join metInventTable
        where metInventTable.ItemId == inventTable.ItemId
    outer join TariffItem from tariffCodeBase
        where tariffCodeBase.RecId == metInventTable.METTariffItemCodeBaseRecid
    outer join RecId, InventSiteId from inventDim
        where inventDim.inventDimId == inventTransferLine.InventDimId
    {
        InventTransferJourLine inventTransferJourLine;
        METTransferOrderLodgements toLodgements;
        boolean lodgementExists = false;

        // Check if lodgement records already exist for this transfer line
        while select Lodgement, BottlesSupplied from toLodgements
        join inventTransferJourLine
            where toLodgements.ReferenceId == inventTransferJourLine.RecId &&
              inventTransferJourLine.TransferId == inventTransferLine.TransferId &&
              inventTransferJourLine.LineNum == inventTransferLine.LineNum &&
              inventTransferJourLine.InventDimId == inventTransferLine.InventDimId
        {
            lodgementExists = true;
            // Populate line with existing lodgement data
            line.BondMark = toLodgements.Lodgement;
            line.BottlesSupplied = toLodgements.BottlesSupplied;

            // Wrap existing lodgement into a list of one container [Lodgement, Qty = 0]
            List singleLodgementList = new List(Types::Container);
            singleLodgementList.addEnd([toLodgements.Lodgement, toLodgements.BottlesSupplied]);

            // Prepare and add the temporary record using existing lodgement
            this.prepareRecordListTmp(
            inventTransferLine,
            inventTable,
            metInventTable,
            tariffCodeBase,
            singleLodgementList,
            true);
        }

        // If no lodgement exists, calculate lodgements based on available excise inventory
        if (!lodgementExists)
        {
            List lodgementList = this.getMetLodgement(
            inventTransferLine.ItemId,
            inventDim.InventSiteId,
            inventTransferLine.QtyTransfer);

            // If no lodgement could be calculated, fallback to default logic
            if (lodgementList.empty())
            {
                this.prepareRecordListTmp(
                    inventTransferLine,
                    inventTable,
                    metInventTable,
                    tariffCodeBase,
                    lodgementList,
                    false);
            }
            else
            {
                ListEnumerator enumerator = lodgementList.getEnumerator();
                container entry;

                // Loop through each calculated lodgement and prepare a record
                while (enumerator.moveNext())
                {
                    entry = enumerator.current();
                    METLodgement lodgementId = conPeek(entry, 1);
                    InventQty availableQty = conPeek(entry, 2);

                    this.prepareRecordListTmp(
                    inventTransferLine,
                    inventTable,
                    metInventTable,
                    tariffCodeBase,
                    lodgementList,
                    true);
                }
            }
        }
    }

    insertList.insertDatabase();
}

/// <summary>
/// dsHeader
/// </summary>
/// <returns>METTOContinuingPermissionNoticeHeaderTmp</returns>
[SRSReportDataSetAttribute(tableStr(METTOContinuingPermissionNoticeHeaderTmp))]
public METTOContinuingPermissionNoticeHeaderTmp dsHeader()
{
    select header;

    return header;
}

/// <summary>
/// dsLines
/// </summary>
/// <returns>METTOContinuingPermissionNoticeLineTmp</returns>
[SRSReportDataSetAttribute(tableStr(METTOContinuingPermissionNoticeLineTmp))]
public METTOContinuingPermissionNoticeLineTmp dsLines()
{
    select line;

    return line;
}

