/// <summary>
/// Get WareHouse address By recevingdock role
/// </summary>
/// <param name = "_inventLocationRecId">Location RecId</param>
/// <param name = "_roleRecId">Role Recid</param>
/// <param name = "_type">LogisticsElectronicAddressMethodType</param>
/// <returns>Locator</returns>
private LogisticsEntityPostalAddressView getWareHousePrimaryAddress(RefRecId _inventLocationRecId)
{
    LogisticsEntityPostalAddressView  logisticsEntityPostalAddressView;

    select firstonly Address from logisticsEntityPostalAddressView
        where logisticsEntityPostalAddressView.Entity == _inventLocationRecId
        && logisticsEntityPostalAddressView.EntityType == LogisticsLocationEntityType::Warehouse
        && logisticsEntityPostalAddressView.ValidFrom <= DateTimeUtil::getSystemDateTime()
        && logisticsEntityPostalAddressView.ValidTo >= DateTimeUtil::getSystemDateTime()
        && logisticsEntityPostalAddressView.IsPrimary == NoYes::Yes;

    return logisticsEntityPostalAddressView;
}

/// <summary>
/// Retrieves lodgement details for a given item and site based on the required transfer quantity.
/// </summary>
/// <param name="_itemId">Item ID for which lodgement entries are needed.</param>
/// <param name="_siteId">Site ID where the inventory is located.</param>
/// <param name="_TransferLineQty">Transfer line quantity to be fulfilled.</param>
/// <returns>
/// A List of containers, where each container holds a pair: [Lodgement ID, Available Quantity].
/// Entries are processed in chronological order and support duplicate lodgement IDs.
/// </returns>
private List getMetLodgement(ItemId _itemId, InventSiteId _siteId, Qty _TransferLineQty)
{
    List resultList = new List(Types::Container);
    METExciseInformationTable metExciseInformationTablePO;
    real remainingQty = abs(_TransferLineQty);

    ttsbegin;
    while select forupdate metExciseInformationTablePO
        order by CreatedDateTime
            where (metExciseInformationTablePO.InventTransType == InventTransType::Purch ||
                metExciseInformationTablePO.InventTransType == InventTransType::TransferOrderReceive) &&
                metExciseInformationTablePO.ItemId == _itemId &&
                metExciseInformationTablePO.SiteId == _siteId &&
                metExciseInformationTablePO.AvailableQty > 0 &&
                metExciseInformationTablePO.LodgementClosed == NoYes::No
    {
        if (remainingQty <= 0)
        {
            break;
        }

        real availableQtyBefore = metExciseInformationTablePO.AvailableQty;
        real bottlesSupplied = 0;

        if (remainingQty >= availableQtyBefore)
        {
            bottlesSupplied = availableQtyBefore;
            remainingQty -= availableQtyBefore;

            metExciseInformationTablePO.AvailableQty = 0;
            metExciseInformationTablePO.LodgementClosed = NoYes::Yes;
        }
        else
        {
            bottlesSupplied = remainingQty;
            metExciseInformationTablePO.AvailableQty = availableQtyBefore - remainingQty;
            remainingQty = 0;
        }

        metExciseInformationTablePO.update();

        // Add [Lodgement, BottlesSupplied] to the result list
        resultList.addEnd([metExciseInformationTablePO.Lodgement, bottlesSupplied]);
    }
    ttscommit;

    return resultList;
}

/// <summary>
/// Prepares and inserts temporary line records for continuing permission notice based on transfer line and lodgement details.
/// </summary>
/// <param name="_inventTransferLine">The transfer line being processed.</param>
/// <param name="_inventTable">The item master record associated with the transfer line.</param>
/// <param name="_metInventTable">Extended item metadata including bottle size, alcohol content, and pack quantity.</param>
/// <param name="_tariffCodeBase">Tariff item code details for customs and excise reporting.</param>
/// <param name="_lodgementList">A list of containers, each containing [Lodgement ID, Available Quantity].</param>
/// <param name="_isLodgement">Flag indicating whether lodgement logic is applied.</param>
/// <remarks>
/// This method performs the following:
/// - Ensures a matching transfer journal line exists.
/// - Creates or updates lodgement records as needed.
/// - Retrieves excise register data for each lodgement.
/// - Populates the temporary line record with item, excise, and tariff details.
/// - Triggers excise register creation for the receiving site if applicable.
/// Lodgements are processed individually to support accurate quantity tracking and reporting.
/// </remarks>
private void prepareRecordListTmp(InventTransferLine _inventTransferLine,
                                  InventTable _inventTable,
                                  METInventTable _metInventTable,
                                  METTariffItemCodeBase _tariffCodeBase,
                                  List _lodgementList, // List of containers: [Lodgement, AvailableQty]
                                  boolean _isLodgement)
{
    const str defaultUOM = 'EA';

    InventTransferJourLine inventTransferJourLine;
    InventSiteId siteId = _inventTransferLine.inventDim().InventSiteId;

    // Retrieve the matching transfer journal line once for reuse
    select firstonly inventTransferJourLine
        where inventTransferJourLine.TransferId == _inventTransferLine.TransferId &&
          inventTransferJourLine.LineNum == _inventTransferLine.LineNum &&
          inventTransferJourLine.InventDimId == _inventTransferLine.InventDimId;

    if (!inventTransferJourLine.RecId)
    {
        return; // Skip if no matching journal line found
    }

    ListEnumerator enum = _lodgementList.getEnumerator();
    container entry;

    while (enum.moveNext())
    {
        entry = enum.current();
        METLodgement lodgementId = conPeek(entry, 1);
        InventQty availableQty = conPeek(entry, 2);

        METTransferOrderLodgements toLodgements;

        // Check if a lodgement record already exists for this line and quantity
        select firstonly forupdate toLodgements
            where toLodgements.ReferenceId == inventTransferJourLine.RecId &&
              toLodgements.Lodgement == lodgementId &&
              toLodgements.BottlesSupplied == availableQty;

        // If not found, create a new lodgement record
        if (!toLodgements.RecId)
        {
            toLodgements.ReferenceId = inventTransferJourLine.RecId;
            toLodgements.Lodgement = lodgementId;
            toLodgements.LodgmentDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
            toLodgements.BottlesSupplied = availableQty;
            toLodgements.insert();
        }

        METExciseRegisterEntry exciseRegister = METExciseRegisterEntry::find(toLodgements.Lodgement,
                                                                             siteId,
                                                                             _inventTransferLine.ItemId);

        line.BondMark = toLodgements.Lodgement;
        line.BottlesSupplied = _isLodgement ? abs(availableQty) : abs(_inventTransferLine.QtyShipped);
        line.ItemId = _inventTransferLine.ItemId;
        line.ItemDescription = _inventTable.productName(SystemParameters::getSystemLanguageId());
        line.BottleSize = _metInventTable.BottleSize;
        line.PackQty = _metInventTable.ItemPack;
        line.Strength = _metInventTable.AlcoholContent;
        line.LitresOfAlcoholCalculated = abs(_metInventTable.BottleSize * _inventTransferLine.QtyShipped * (_metInventTable.AlcoholContent / 100));
        line.ValueTIU = exciseRegister.TIUV;
        line.TariffItem = _tariffCodeBase.TariffItem;
        line.CountryOfOrigin = _metInventTable.CountryCode;
        line.StatCode = _metInventTable.statcode();
        line.ValueDuty = exciseRegister.DutyRateReceived;
        line.TransferId = inventTransferTable.TransferId;
        line.BundleReportHeaderGuidStr = bundleHeaderReportGuid;
        line.ContinuingPermissionHeaderGuidStr = headerReportGuid;

        insertList.add(line);

        // Auto-create excise register entry for receiving site
        if (METExciseRegisterEntry::shouldCreateExciseRegisterEntriyReceive(inventTransferJourLine))
        {
            METExciseRegisterEntry::createExciseRegisterEntriyReceive(toLodgements);
        }
    }
}
